interface InfiniteScrollProps {
  onLoadMore: (page: number) => Promise<T[]>;
  renderItem: (item: T) => React.ReactNode;
  threshold?: number;
}

function InfiniteScroll<T>({ onLoadMore, renderItem, threshold = 0.5 }: InfiniteScrollProps) {
  const [items, setItems] = useState<T[]>([]);
  const [page, setPage] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const sentinelRef = useRef<HTMLDivElement>(null);

  const handleLoadMore = useCallback(async () => {
    if (isLoading || !hasMore) return;

    setIsLoading(true);
    try {
      const newItems = await onLoadMore(page + 1);
      setItems((prev) => [...prev, ...newItems]);
      setPage((prev) => prev + 1);
      setHasMore(newItems.length > 0);
    } catch (error) {
      console.error('Failed to load more items:', error);
    } finally {
      setIsLoading(false);
    }
  }, [page, isLoading, hasMore, onLoadMore]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          handleLoadMore();
        }
      },
      { threshold }
    );

    if (sentinelRef.current) {
      observer.observe(sentinelRef.current);
    }

    return () => {
      observer.disconnect();
    };
  }, [handleLoadMore]);

  return (
    <div>
      {items.map((item, idx) => (
        <div key={idx}>{renderItem(item)}</div>
      ))}
      {isLoading && <div>Loading...</div>}
      {hasMore && <div ref={sentinelRef} style={{ height: '20px' }} />}
      {!hasMore && <div>No more items</div>}
    </div>
  );
}

// Usage:
<InfiniteScroll
  onLoadMore={async (page) => {
    const response = await fetch(`/api/items?page=${page}`);
    return response.json();
  }}
  renderItem={(item) => <ItemCard item={item} />}
  threshold={0.8}
